<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { descargarDocumento, detalleEvaluacion, listarEvaluaciones, notificarProveedores, resolverProceso, validarProveedor, type ProcesoEvaluacion, type ProveedorOferta, type ResultadoTecnico } from '../services/evaluacionTecnica'
const rows=ref<ProcesoEvaluacion[]>([]),detail=ref<ProcesoEvaluacion|null>(null),total=ref(0),lastPage=ref(1),estados=ref<Array<{id:number;nombre:string}>>([]),etapas=ref<Array<{id:number;nombre:string}>>([]),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),providerModal=ref(false),selectedProvider=ref<ProveedorOferta|null>(null)
const filters=reactive({q:'',inicio_desde:'',fin_hasta:'',estado:'',etapa_vigente:'',page:1}),review=reactive<{resultado:ResultadoTecnico;comentario:string}>({resultado:'aprobado',comentario:''})
const evaluated=computed(()=>detail.value?.proveedores?.filter(x=>x.validacion).length||0),rejected=computed(()=>detail.value?.proveedores?.filter(x=>x.validacion?.resultado==='rechazado').length||0),allEvaluated=computed(()=>Boolean(detail.value?.proveedores?.length&&evaluated.value===detail.value.proveedores.length))
async function load(page=1){filters.page=page;loading.value=true;error.value='';try{const response=await listarEvaluaciones(filters);rows.value=response.data;total.value=response.total;lastPage.value=response.last_page;estados.value=response.estados;etapas.value=response.etapas}catch(cause){error.value=message(cause)}finally{loading.value=false}}
async function open(item:ProcesoEvaluacion){loading.value=true;try{detail.value=await detalleEvaluacion(item.id)}catch(cause){error.value=message(cause)}finally{loading.value=false}}
function reviewProvider(provider:ProveedorOferta){selectedProvider.value=provider;review.resultado=provider.validacion?.resultado||'aprobado';review.comentario=provider.validacion?.comentario||'';providerModal.value=true}
async function saveReview(){if(!detail.value||!selectedProvider.value)return;if(review.resultado==='rechazado'&&!review.comentario.trim()){error.value='Ingrese el motivo del rechazo.';return}saving.value=true;try{await validarProveedor(detail.value.id,selectedProvider.value.id,review.resultado,review.comentario);success.value='Evaluación del proveedor registrada.';providerModal.value=false;await open(detail.value)}catch(cause){error.value=message(cause)}finally{saving.value=false}}
async function resolve(result:'aprobar'|'rechazar'){if(!detail.value)return;let comment='';if(result==='rechazar'){comment=prompt('Ingrese el motivo del rechazo del proceso:')||'';if(!comment)return}if(!confirm(`¿${result} el proceso técnico?`))return;try{await resolverProceso(detail.value.id,result,comment);success.value=`Proceso ${result==='aprobar'?'aprobado':'rechazado'} correctamente.`;detail.value=null;await load()}catch(cause){error.value=message(cause)}}
async function notify(provider?:ProveedorOferta){if(!detail.value||!confirm(provider?'¿Notificar observación a este proveedor?':'¿Notificar a todos los proveedores observados?'))return;try{await notificarProveedores(detail.value.id,provider?.id);success.value='Notificación enviada correctamente.';await open(detail.value)}catch(cause){error.value=message(cause)}}
function badge(result?:ResultadoTecnico){return result?.replace(' ','-')||'pendiente'}function message(cause:unknown){return cause instanceof Error?cause.message:'No se pudo completar la operación.'}onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Logística / Evaluación técnica</nav><header class="hero"><div class="mark">ET</div><div><small>MIA · Logística</small><h1>Evaluación técnica de ofertas</h1><p>Valida las propuestas presentadas por los postores de cada proceso.</p></div><strong>{{total}} procesos</strong></header><p v-if="success" class="flash">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><section class="filters"><label>Proceso<input v-model.trim="filters.q" placeholder="Nombre o descripción" @keyup.enter="load(1)"></label><label>Inicio desde<input v-model="filters.inicio_desde" type="date"></label><label>Fin hasta<input v-model="filters.fin_hasta" type="date"></label><label>Etapa<select v-model="filters.etapa_vigente"><option value="">Todas</option><option v-for="stage in etapas" :key="stage.id" :value="stage.id">{{stage.nombre}}</option></select></label><button @click="load(1)">Buscar</button></section><div v-if="loading&&!detail" class="empty">Cargando evaluaciones…</div><div v-else-if="!rows.length" class="empty">No existen procesos pendientes de validación técnica.</div><section v-else class="table"><header><span>Código</span><span>Proceso</span><span>Etapa</span><span>Postores</span><span>Estado</span><span>Fecha</span><span></span></header><article v-for="item in rows" :key="item.id"><b>#{{String(item.id).padStart(6,'0')}}</b><div><b>{{item.nombre}}</b><small>{{item.descripcion}}</small></div><span>{{item.etapa_nombre||'Validación técnica'}}</span><span>{{item.postores_count}}</span><em>{{item.estado_nombre}}</em><time>{{item.created_at}}</time><button @click="open(item)">Evaluar</button></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="filters.page<=1" @click="load(filters.page-1)">Anterior</button><span>{{filters.page}} / {{lastPage}}</span><button :disabled="filters.page>=lastPage" @click="load(filters.page+1)">Siguiente</button></footer>
<div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="modal wide"><header><div><small>Proceso #{{detail.id}}</small><h2>{{detail.nombre}}</h2><p>{{detail.descripcion}}</p></div><button @click="detail=null">×</button></header><section class="summary"><div><b>{{detail.proveedores?.length||0}}</b><span>Postores</span></div><div><b>{{evaluated}}</b><span>Evaluados</span></div><div class="bad"><b>{{rejected}}</b><span>Observados</span></div><div><b>{{detail.etapa_nombre||'—'}}</b><span>Etapa vigente</span></div></section><h3>Propuestas y validación por proveedor</h3><div class="providers"><article v-for="provider in detail.proveedores" :key="provider.id"><header><div><b>{{provider.razon_social}}</b><small>{{provider.ruc}} · {{provider.email}}</small></div><em :class="badge(provider.validacion?.resultado)">{{provider.validacion?.resultado||'Pendiente'}}</em></header><div class="docs"><button v-for="doc in provider.documentos" :key="doc.id" @click="descargarDocumento(detail!.id,doc.id,doc.nombre)">▣ {{doc.nombre}}</button><span v-if="!provider.documentos.length">Sin documentos</span></div><p v-if="provider.validacion?.comentario">{{provider.validacion.comentario}}</p><footer><button @click="reviewProvider(provider)">{{provider.validacion?'Actualizar evaluación':'Evaluar oferta'}}</button><button v-if="provider.validacion?.resultado==='rechazado'" class="notify" @click="notify(provider)">Notificar observación</button><details v-if="provider.historial.length"><summary>Historial ({{provider.historial.length}})</summary><div v-for="entry in provider.historial" :key="entry.id"><b>Ronda {{entry.ronda}} · {{entry.resultado}}</b><span>{{entry.fecha}} · {{entry.usuario}}</span><p>{{entry.comentario}}</p></div></details></footer></article></div><footer class="process-actions"><button class="clear" @click="detail=null">Cerrar</button><button v-if="rejected" class="notify" @click="notify()">Notificar observados</button><button class="reject" @click="resolve('rechazar')">Rechazar proceso</button><button :disabled="!allEvaluated||rejected>0" @click="resolve('aprobar')">Aprobar proceso</button></footer></section></div>
<div v-if="providerModal" class="backdrop top" @mousedown.self="providerModal=false"><form class="modal" @submit.prevent="saveReview"><header><div><small>Validación técnica</small><h2>{{selectedProvider?.razon_social}}</h2></div><button type="button" @click="providerModal=false">×</button></header><label>Resultado<select v-model="review.resultado"><option value="aprobado">Aprobado</option><option value="rechazado">Rechazado</option><option value="sin evaluacion">No requiere evaluación</option></select></label><label>Comentario {{review.resultado==='rechazado'?'*':''}}<textarea v-model.trim="review.comentario" maxlength="1000" rows="5" placeholder="Sustento técnico u observaciones"/></label><footer><button type="button" class="clear" @click="providerModal=false">Cancelar</button><button :disabled="saving">Guardar evaluación</button></footer></form></div></div></template>
<style scoped>
