tant;background:#edf1f3!important}@media(max-width:900px){.table>header{display:none}.table>article{grid-template-columns:1fr}.filters{align-items:stretch;flex-direction:column}.summary{grid-template-columns:repeat(2,1fr)}.hero{flex-wrap:wrap}.hero strong{margin-left:0}}
